<?php
declare(strict_types=1);
final class PCPasswordResetRepository {
 public static function create(PDO $p,string $email):?array{$s=$p->prepare('SELECT id,email,username FROM users WHERE email=? AND email_verified_at IS NOT NULL LIMIT 1');$s->execute([$email]);$u=$s->fetch();if(!$u)return null;$token=bin2hex(random_bytes(32));$p->beginTransaction();try{$p->prepare('DELETE FROM password_reset_tokens WHERE user_id=?')->execute([$u['id']]);$p->prepare('INSERT INTO password_reset_tokens (user_id,token_hash,expires_at) VALUES (?,?,DATE_ADD(UTC_TIMESTAMP(),INTERVAL 1 HOUR))')->execute([$u['id'],hash('sha256',$token)]);$p->commit();return ['token'=>$token,'email'=>$u['email'],'username'=>$u['username']];}catch(Throwable $e){if($p->inTransaction())$p->rollBack();throw $e;}}
 public static function reset(PDO $p,string $token,string $password):bool{$p->beginTransaction();try{$s=$p->prepare('SELECT id,user_id FROM password_reset_tokens WHERE token_hash=? AND expires_at>UTC_TIMESTAMP() LIMIT 1 FOR UPDATE');$s->execute([hash('sha256',$token)]);$r=$s->fetch();if(!$r){$p->rollBack();return false;}$p->prepare('UPDATE users SET password_hash=? WHERE id=?')->execute([password_hash($password,PASSWORD_DEFAULT),$r['user_id']]);$p->prepare('DELETE FROM auth_tokens WHERE user_id=?')->execute([$r['user_id']]);$p->prepare('DELETE FROM password_reset_tokens WHERE user_id=?')->execute([$r['user_id']]);$p->commit();return true;}catch(Throwable $e){if($p->inTransaction())$p->rollBack();throw $e;}}
}
